package org.apache.commons.math3.geometry.euclidean.threed;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.geometry.euclidean.oned.Interval;
import org.apache.commons.math3.geometry.euclidean.oned.IntervalsSet;
import org.apache.commons.math3.geometry.euclidean.oned.Vector1D;
import org.apache.commons.math3.geometry.euclidean.threed.Vector3D;
import org.apache.commons.math3.geometry.partitioning.Region.Location;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Unit tests for SubLine#intersection.
 */
public class SubLine_intersection_TriageGen5Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testIntersection_IncludeEndPoints_BothInside() {
        // Line 1: (0,0,0) to (2,0,0)
        SubLine subLine1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(2, 0, 0));
        // Line 2: (1, -1, 0) to (1, 1, 0) -> Intersects at (1,0,0) which is inside subLine1
        SubLine subLine2 = new SubLine(new Vector3D(1, -1, 0), new Vector3D(1, 1, 0));

        Vector3D result = subLine1.intersection(subLine2, true);
        assertEquals(new Vector3D(1, 0, 0), result);
    }

    @Test
    public void testIntersection_IncludeEndPoints_OneOnBoundary() {
        // Line 1: (0,0,0) to (2,0,0)
        SubLine subLine1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(2, 0, 0));
        // Line 2: (2, -1, 0) to (2, 1, 0) -> Intersects at (2,0,0) which is boundary of subLine1
        SubLine subLine2 = new SubLine(new Vector3D(2, -1, 0), new Vector3D(2, 1, 0));

        Vector3D result = subLine1.intersection(subLine2, true);
        assertEquals(new Vector3D(2, 0, 0), result);
    }

    @Test
    public void testIntersection_IncludeEndPoints_OneOutside() {
        // Line 1: (0,0,0) to (2,0,0)
        SubLine subLine1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(2, 0, 0));
        // Line 2: (3, -1, 0) to (3, 1, 0) -> Intersects at (3,0,0) which is outside subLine1
        SubLine subLine2 = new SubLine(new Vector3D(3, -1, 0), new Vector3D(3, 1, 0));

        Vector3D result = subLine1.intersection(subLine2, true);
        assertNull(result);
    }

    @Test
    public void testIntersection_ExcludeEndPoints_BothInside() {
        // Line 1: (0,0,0) to (2,0,0)
        SubLine subLine1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(2, 0, 0));
        // Line 2: (1, -1, 0) to (1, 1, 0)
        SubLine subLine2 = new SubLine(new Vector3D(1, -1, 0), new Vector3D(1, 1, 0));

        Vector3D result = subLine1.intersection(subLine2, false);
        assertEquals(new Vector3D(1, 0, 0), result);
    }

    @Test
    public void testIntersection_ExcludeEndPoints_OneOnBoundary() {
        // Line 1: (0,0,0) to (2,0,0)
        SubLine subLine1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(2, 0, 0));
        // Line 2: (2, -1, 0) to (2, 1, 0) -> Intersects at (2,0,0)
        SubLine subLine2 = new SubLine(new Vector3D(2, -1, 0), new Vector3D(2, 1, 0));

        // If excludeEndPoints is false, boundary (Location.BOUNDARY) is not Location.INSIDE
        Vector3D result = subLine1.intersection(subLine2, false);
        assertNull(result);
    }

    @Test
    public void testIntersection_ExcludeEndPoints_BothOutside() {
        // Line 1: (0,0,0) to (2,0,0)
        SubLine subLine1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(2, 0, 0));
        // Line 2: (3, -1, 0) to (3, 1, 0)
        SubLine subLine2 = new SubLine(new Vector3D(3, -1, 0), new Vector3D(3, 1, 0));

        Vector3D result = subLine1.intersection(subLine2, false);
        assertNull(result);
    }

    @Test
    public void testIntersection_NoIntersectionOnInfiniteLines() {
        // Parallel lines
        SubLine subLine1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(2, 0, 0));
        SubLine subLine2 = new SubLine(new Vector3D(0, 1, 0), new Vector3D(2, 1, 0));

        // Note: Depending on implementation of line.intersection, this might throw exception 
        // or return null. Assuming it returns null or handles it gracefully as per Apache Math.
        // If line.intersection throws MathIllegalArgumentException, this test would need adjustment.
        try {
            Vector3D result = subLine1.intersection(subLine2, true);
            assertNull(result);
        } catch (IllegalArgumentException e) {
            // Acceptable if implementation throws exception for parallel lines
        }
    }
}
